    json.dump(payload,open(f'articles3/{k}.payload.json','w'),ensure_ascii=False)
    for att in range(3):
        r=subprocess.run(['curl','-sS','-n','-m','120','https://arcadia-tour.com/wp-json/wp/v2/posts','-X','POST','-H','Content-Type: application/json','--data-binary',f'@articles3/{k}.payload.json'],capture_output=True,text=True).stdout
